// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    address initialFrom = 0x9797055B68C5DadDE6b3c7d5D80C9CFE2eecE6c9;

    function setUp() public { c = new C(); }

    function testFuzz_property(address[] memory _tos, uint256[] memory v) public {
        vm.assume(_tos.length > 0 && _tos.length == v.length);
        for(uint i = 0; i < _tos.length; i++) {
            v[i] = bound(v[i], 0, 1000);
        }

        vm.prank(initialFrom);
        (bool success, ) = address(c).call(abi.encodeWithSelector(c.transfer.selector, _tos, v));

        assertTrue(c.from() == initialFrom);
    }
}

